import{G as e,W as t,n,rt as r}from"./chunks/framework.CJ3GlOSn.js";var i=JSON.parse(`{"title":"AdminLog","description":"","frontmatter":{},"headers":[],"relativePath":"03-developer/models/adminlog.md","filePath":"03-developer/models/adminlog.md"}`),a={name:`03-developer/models/adminlog.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="adminlog" tabindex="-1">AdminLog <a class="header-anchor" href="#adminlog" aria-label="Permalink to “AdminLog”">​</a></h1><p>Model reference · <code>App\\Models\\AdminLog</code></p><h3 id="_1-model" tabindex="-1">1. Model <a class="header-anchor" href="#_1-model" aria-label="Permalink to “1. Model”">​</a></h3><p>The model for recording system administrators&#39; actions, including those of Admin, Developer, or User accounts. It is designed to log operations performed on system resources and can be used as an activity history, work report, and accountability tool for administrators in organizational systems.</p><ul><li>For example, user x edited category z.</li><li>Another example: user y deleted a product.</li></ul><p>Executed operations are recorded, not activities that are purely for display; for example, simply viewing a list of information does not create a log.</p><h3 id="_2-table-admin-logs" tabindex="-1">2. Table: <code>admin_logs</code> <a class="header-anchor" href="#_2-table-admin-logs" aria-label="Permalink to “2. Table: admin_logs”">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Nullable</th><th>Comment</th></tr></thead><tbody><tr><td><code>id</code></td><td>bigint unsigned</td><td>No</td><td>Log identifier</td></tr><tr><td><code>user_id</code></td><td>bigint unsigned</td><td>No</td><td>Identifier of the user who performed the operation</td></tr><tr><td><code>action</code></td><td>varchar(255)</td><td>No</td><td>Type of operation performed</td></tr><tr><td><code>loggable_type</code></td><td>varchar(255)</td><td>Yes</td><td>Type of model or resource affected by the operation</td></tr><tr><td><code>loggable_id</code></td><td>bigint unsigned</td><td>Yes</td><td>Identifier of the record affected by the operation</td></tr><tr><td><code>created_at</code></td><td>timestamp</td><td>Yes</td><td>Log creation time</td></tr><tr><td><code>updated_at</code></td><td>timestamp</td><td>Yes</td><td>Time the log was last edited</td></tr></tbody></table><h3 id="_3-extra-description-of-table-fields" tabindex="-1">3. Extra description of table fields <a class="header-anchor" href="#_3-extra-description-of-table-fields" aria-label="Permalink to “3. Extra description of table fields”">​</a></h3><p><strong><code>admin_logs.user_id</code></strong></p><p>Specifies which user performed the operation. This field references the <code>users</code> table.</p><p>Deleting a user associated with a log is not permitted because of the database&#39;s <code>ON DELETE RESTRICT</code> constraint; this preserves users&#39; activity history.</p><p>Related model documentation: <a href="./user.html">User</a>.</p><p><strong><code>admin_logs.action</code></strong></p><p>Specifies the type of operation performed. Common examples include:</p><ul><li><code>create</code> - creates a record</li><li><code>update</code> - edits a record, including operations defined as <code>bringup</code> in the system logic.</li><li><code>delete</code> - deletes a record</li><li><code>restore</code> - restores a deleted record</li></ul><p>Custom operations defined in Controllers can also be recorded in this field. Its value indicates the type of operation, not the full details of the changes made.</p><p><strong><code>admin_logs.loggable_type</code> and <code>admin_logs.loggable_id</code></strong></p><p>Together, these fields specify which model and record the operation was performed on. This structure is designed for polymorphic references to different resources.</p><p>For example, if an operation is performed on a product, <code>loggable_type</code> specifies the product model type, and <code>loggable_id</code> specifies that product&#39;s identifier.</p><p>Both fields are optional; therefore, a log can be recorded without a reference to a specific record.</p><p><strong>Bulk actions</strong></p><p>If an administrator performs a bulk action on multiple records, a separate log is recorded for each affected record. This makes it possible to review the activity history of each record independently.</p><p><strong>Organizational use and accountability</strong></p><p>This table can be used to review administrators&#39; operational histories, prepare activity reports, and track operations performed in organizational systems.</p><p>However, the presence of a record in this table alone does not conclusively prove every detail of an operation. The table stores the operation type, the user who performed it, and the related reference; it does not necessarily include the values before and after a change or other execution details.</p><h3 id="_4-methods" tabindex="-1">4. Methods <a class="header-anchor" href="#_4-methods" aria-label="Permalink to “4. Methods”">​</a></h3><p><strong><code>user()</code></strong></p><p>A <code>belongsTo</code> relationship with the <code>User</code> model; returns the user who performed the recorded operation.</p><p>Related model documentation: <a href="./user.html">User</a>.</p>`,30)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};